    /// Program errors for conditional_vault
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum ConditionalvaultError {
        /// An assertion failed
        AssertFailed = 6000,

        /// Insufficient underlying token balance to mint this amount of
        /// conditional tokens
        InsufficientUnderlyingTokens = 6001,

        /// Insufficient conditional token balance to merge this `amount`
        InsufficientConditionalTokens = 6002,

        /// This `vault_underlying_token_account` is not this vault's
        /// `underlying_token_account`
        InvalidVaultUnderlyingTokenAccount = 6003,

        /// This conditional token mint is not this vault's conditional token
        /// mint
        InvalidConditionalTokenMint = 6004,

        /// Question needs to be resolved before users can redeem conditional
        /// tokens for underlying tokens
        CantRedeemConditionalTokens = 6005,

        /// Questions need 2 or more conditions
        InsufficientNumConditions = 6006,

        /// Invalid number of payout numerators
        InvalidNumPayoutNumerators = 6007,

        /// Client needs to pass in the list of conditional mints for a vault
        /// followed by the user's token accounts for those tokens
        InvalidConditionals = 6008,

        /// Conditional mint not in vault
        ConditionalMintMismatch = 6009,

        /// Unable to deserialize a conditional token mint
        BadConditionalMint = 6010,

        /// Unable to deserialize a conditional token account
        BadConditionalTokenAccount = 6011,

        /// User conditional token account mint does not match conditional mint
        ConditionalTokenMintMismatch = 6012,

        /// Payouts must sum to 1 or more
        PayoutZero = 6013,

        /// Question already resolved
        QuestionAlreadyResolved = 6014,

        /// Conditional token metadata already set
        ConditionalTokenMetadataAlreadySet = 6015,

        /// Conditional token account is not owned by the authority
        UnauthorizedConditionalTokenAccount = 6016,

        /// Payout numerators are too large, causing an overflow
        InvalidPayoutNumerators = 6017,

        /// Questions can only have up to 10 outcomes
        TooManyOutcomes = 6018,
    }

    impl ConditionalvaultError {
        /// Get the error code
        pub fn code(&self) -> u32 {
            *self as u32
        }

        /// Get the error message
        pub fn msg(&self) -> &'static str {
            match self {

                Self::AssertFailed => "An assertion failed",

                Self::InsufficientUnderlyingTokens => "Insufficient underlying token balance to mint this amount of conditional tokens",

                Self::InsufficientConditionalTokens => "Insufficient conditional token balance to merge this `amount`",

                Self::InvalidVaultUnderlyingTokenAccount => "This `vault_underlying_token_account` is not this vault's `underlying_token_account`",

                Self::InvalidConditionalTokenMint => "This conditional token mint is not this vault's conditional token mint",

                Self::CantRedeemConditionalTokens => "Question needs to be resolved before users can redeem conditional tokens for underlying tokens",

                Self::InsufficientNumConditions => "Questions need 2 or more conditions",

                Self::InvalidNumPayoutNumerators => "Invalid number of payout numerators",

                Self::InvalidConditionals => "Client needs to pass in the list of conditional mints for a vault followed by the user's token accounts for those tokens",

                Self::ConditionalMintMismatch => "Conditional mint not in vault",

                Self::BadConditionalMint => "Unable to deserialize a conditional token mint",

                Self::BadConditionalTokenAccount => "Unable to deserialize a conditional token account",

                Self::ConditionalTokenMintMismatch => "User conditional token account mint does not match conditional mint",

                Self::PayoutZero => "Payouts must sum to 1 or more",

                Self::QuestionAlreadyResolved => "Question already resolved",

                Self::ConditionalTokenMetadataAlreadySet => "Conditional token metadata already set",

                Self::UnauthorizedConditionalTokenAccount => "Conditional token account is not owned by the authority",

                Self::InvalidPayoutNumerators => "Payout numerators are too large, causing an overflow",

                Self::TooManyOutcomes => "Questions can only have up to 10 outcomes",

            }
        }

        /// Try to convert from error code
        pub fn from_code(code: u32) -> Option<Self> {
            match code {
                6000 => Some(Self::AssertFailed),

                6001 => Some(Self::InsufficientUnderlyingTokens),

                6002 => Some(Self::InsufficientConditionalTokens),

                6003 => Some(Self::InvalidVaultUnderlyingTokenAccount),

                6004 => Some(Self::InvalidConditionalTokenMint),

                6005 => Some(Self::CantRedeemConditionalTokens),

                6006 => Some(Self::InsufficientNumConditions),

                6007 => Some(Self::InvalidNumPayoutNumerators),

                6008 => Some(Self::InvalidConditionals),

                6009 => Some(Self::ConditionalMintMismatch),

                6010 => Some(Self::BadConditionalMint),

                6011 => Some(Self::BadConditionalTokenAccount),

                6012 => Some(Self::ConditionalTokenMintMismatch),

                6013 => Some(Self::PayoutZero),

                6014 => Some(Self::QuestionAlreadyResolved),

                6015 => Some(Self::ConditionalTokenMetadataAlreadySet),

                6016 => Some(Self::UnauthorizedConditionalTokenAccount),

                6017 => Some(Self::InvalidPayoutNumerators),

                6018 => Some(Self::TooManyOutcomes),

                _ => None,
            }
        }
    }

    impl std::fmt::Display for ConditionalvaultError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}: {}", self.code(), self.msg())
        }
    }

    impl std::error::Error for ConditionalvaultError {}

