    // ------------------------------------------------------------------------

    /// Program errors for launchpad_v7
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum Launchpadv7Error {
        /// Invalid amount
        InvalidAmount = 6000,

        /// Supply must be zero
        SupplyNonZero = 6001,

        /// Launch period must be between 1 hour and 2 weeks
        InvalidSecondsForLaunch = 6002,

        /// Insufficient funds
        InsufficientFunds = 6003,

        /// Token mint key must end in 'meta'
        InvalidTokenKey = 6004,

        /// Invalid launch state
        InvalidLaunchState = 6005,

        /// Launch period not over
        LaunchPeriodNotOver = 6006,

        /// Launch is complete, no more funding allowed
        LaunchExpired = 6007,

        /// For you to get a refund, either the launch needs to be in a
        /// refunding state or the launch must have been over-committed
        LaunchNotRefunding = 6008,

        /// Launch must be initialized to be started
        LaunchNotInitialized = 6009,

        /// Freeze authority can't be set on launchpad tokens
        FreezeAuthoritySet = 6010,

        /// Monthly spending limit must be less than 1/6th of the minimum raise
        /// amount and cannot be 0
        InvalidMonthlySpendingLimit = 6011,

        /// There can only be at most 10 monthly spending limit members
        InvalidMonthlySpendingLimitMembers = 6012,

        /// Cannot do more than a 50% premine, minimum is 10 atoms of token
        InvalidPriceBasedPremineAmount = 6013,

        /// Insiders must be forced to wait at least 18 months before unlocking
        /// their tokens
        InvalidPerformancePackageMinUnlockTime = 6014,

        /// Launch authority must be set to complete the launch until 2 days
        /// after closing
        LaunchAuthorityNotSet = 6015,

        /// The final amount raised must be greater than or equal to the minimum
        /// raise amount
        FinalRaiseAmountTooLow = 6016,

        /// Tokens already claimed
        TokensAlreadyClaimed = 6017,

        /// Money already refunded
        MoneyAlreadyRefunded = 6018,

        /// An invariant was violated. You should get in contact with the
        /// MetaDAO team if you see this
        InvariantViolated = 6019,

        /// Launch must be live to be closed
        LaunchNotLive = 6020,

        /// Minimum raise amount must be greater than or equal to $0.5 so that
        /// there's enough liquidity for the launch
        InvalidMinimumRaiseAmount = 6021,

        /// The final raise amount has already been set
        FinalRaiseAmountAlreadySet = 6022,

        /// Total approved amount must be greater than or equal to the minimum
        /// raise amount
        TotalApprovedAmountTooLow = 6023,

        /// Invalid additional tokens recipient - should be set if additional
        /// tokens amount is greater than 0
        InvalidAdditionalTokensRecipient = 6024,

        /// No additional tokens recipient set
        NoAdditionalTokensRecipientSet = 6025,

        /// Additional tokens already claimed
        AdditionalTokensAlreadyClaimed = 6026,

        /// Funding record approval period is over
        FundingRecordApprovalPeriodOver = 6027,

        /// Performance package already initialized
        PerformancePackageAlreadyInitialized = 6028,

        /// Invalid DAO
        InvalidDao = 6029,

        /// Accumulator activation delay must be less than the launch duration
        InvalidAccumulatorActivationDelaySeconds = 6030,
    }

    impl Launchpadv7Error {
        /// Get the error code
        pub fn code(&self) -> u32 {
            *self as u32
        }

        /// Get the error message
        pub fn msg(&self) -> &'static str {
            match self {

                Self::InvalidAmount => "Invalid amount",

                Self::SupplyNonZero => "Supply must be zero",

                Self::InvalidSecondsForLaunch => "Launch period must be between 1 hour and 2 weeks",

                Self::InsufficientFunds => "Insufficient funds",

                Self::InvalidTokenKey => "Token mint key must end in 'meta'",

                Self::InvalidLaunchState => "Invalid launch state",

                Self::LaunchPeriodNotOver => "Launch period not over",

                Self::LaunchExpired => "Launch is complete, no more funding allowed",

                Self::LaunchNotRefunding => "For you to get a refund, either the launch needs to be in a refunding state or the launch must have been over-committed",

                Self::LaunchNotInitialized => "Launch must be initialized to be started",

                Self::FreezeAuthoritySet => "Freeze authority can't be set on launchpad tokens",

                Self::InvalidMonthlySpendingLimit => "Monthly spending limit must be less than 1/6th of the minimum raise amount and cannot be 0",

                Self::InvalidMonthlySpendingLimitMembers => "There can only be at most 10 monthly spending limit members",

                Self::InvalidPriceBasedPremineAmount => "Cannot do more than a 50% premine, minimum is 10 atoms of token",

                Self::InvalidPerformancePackageMinUnlockTime => "Insiders must be forced to wait at least 18 months before unlocking their tokens",

                Self::LaunchAuthorityNotSet => "Launch authority must be set to complete the launch until 2 days after closing",

                Self::FinalRaiseAmountTooLow => "The final amount raised must be greater than or equal to the minimum raise amount",

                Self::TokensAlreadyClaimed => "Tokens already claimed",

                Self::MoneyAlreadyRefunded => "Money already refunded",

                Self::InvariantViolated => "An invariant was violated. You should get in contact with the MetaDAO team if you see this",

                Self::LaunchNotLive => "Launch must be live to be closed",

                Self::InvalidMinimumRaiseAmount => "Minimum raise amount must be greater than or equal to $0.5 so that there's enough liquidity for the launch",

                Self::FinalRaiseAmountAlreadySet => "The final raise amount has already been set",

                Self::TotalApprovedAmountTooLow => "Total approved amount must be greater than or equal to the minimum raise amount",

                Self::InvalidAdditionalTokensRecipient => "Invalid additional tokens recipient - should be set if additional tokens amount is greater than 0",

                Self::NoAdditionalTokensRecipientSet => "No additional tokens recipient set",

                Self::AdditionalTokensAlreadyClaimed => "Additional tokens already claimed",

                Self::FundingRecordApprovalPeriodOver => "Funding record approval period is over",

                Self::PerformancePackageAlreadyInitialized => "Performance package already initialized",

                Self::InvalidDao => "Invalid DAO",

                Self::InvalidAccumulatorActivationDelaySeconds => "Accumulator activation delay must be less than the launch duration",

            }
        }

        /// Try to convert from error code
        pub fn from_code(code: u32) -> Option<Self> {
            match code {
                6000 => Some(Self::InvalidAmount),

                6001 => Some(Self::SupplyNonZero),

                6002 => Some(Self::InvalidSecondsForLaunch),

                6003 => Some(Self::InsufficientFunds),

                6004 => Some(Self::InvalidTokenKey),

                6005 => Some(Self::InvalidLaunchState),

                6006 => Some(Self::LaunchPeriodNotOver),

                6007 => Some(Self::LaunchExpired),

                6008 => Some(Self::LaunchNotRefunding),

                6009 => Some(Self::LaunchNotInitialized),

                6010 => Some(Self::FreezeAuthoritySet),

                6011 => Some(Self::InvalidMonthlySpendingLimit),

                6012 => Some(Self::InvalidMonthlySpendingLimitMembers),

                6013 => Some(Self::InvalidPriceBasedPremineAmount),

                6014 => Some(Self::InvalidPerformancePackageMinUnlockTime),

                6015 => Some(Self::LaunchAuthorityNotSet),

                6016 => Some(Self::FinalRaiseAmountTooLow),

                6017 => Some(Self::TokensAlreadyClaimed),

                6018 => Some(Self::MoneyAlreadyRefunded),

                6019 => Some(Self::InvariantViolated),

                6020 => Some(Self::LaunchNotLive),

                6021 => Some(Self::InvalidMinimumRaiseAmount),

                6022 => Some(Self::FinalRaiseAmountAlreadySet),

                6023 => Some(Self::TotalApprovedAmountTooLow),

                6024 => Some(Self::InvalidAdditionalTokensRecipient),

                6025 => Some(Self::NoAdditionalTokensRecipientSet),

                6026 => Some(Self::AdditionalTokensAlreadyClaimed),

                6027 => Some(Self::FundingRecordApprovalPeriodOver),

                6028 => Some(Self::PerformancePackageAlreadyInitialized),

                6029 => Some(Self::InvalidDao),

                6030 => Some(Self::InvalidAccumulatorActivationDelaySeconds),

                _ => None,
            }
        }
    }

    impl std::fmt::Display for Launchpadv7Error {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}: {}", self.code(), self.msg())
        }
    }

    impl std::error::Error for Launchpadv7Error {}

