    /// Program errors for futarchy
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum FutarchyError {
        /// Amms must have been created within 5 minutes (counted in slots) of
        /// proposal initialization
        AmmTooOld = 6000,

        /// An amm has an `initial_observation` that doesn't match the `dao`'s
        /// config
        InvalidInitialObservation = 6001,

        /// An amm has a `max_observation_change_per_update` that doesn't match
        /// the `dao`'s config
        InvalidMaxObservationChange = 6002,

        /// An amm has a `start_delay_slots` that doesn't match the `dao`'s
        /// config
        InvalidStartDelaySlots = 6003,

        /// One of the vaults has an invalid `settlement_authority`
        InvalidSettlementAuthority = 6004,

        /// Proposal is too young to be executed or rejected
        ProposalTooYoung = 6005,

        /// Markets too young for proposal to be finalized. TWAP might need to
        /// be cranked
        MarketsTooYoung = 6006,

        /// This proposal has already been finalized
        ProposalAlreadyFinalized = 6007,

        /// A conditional vault has an invalid nonce. A nonce should encode the
        /// proposal number
        InvalidVaultNonce = 6008,

        /// This proposal can't be executed because it isn't in the passed state
        ProposalNotPassed = 6009,

        /// More liquidity needs to be in the AMM to launch this proposal
        InsufficientLiquidity = 6010,

        /// Proposal duration must be longer 1 day and longer than 2 times the
        /// TWAP start delay
        ProposalDurationTooShort = 6011,

        /// Pass threshold must be less than 10%
        PassThresholdTooHigh = 6012,

        /// Question must have exactly 2 outcomes for binary futarchy
        QuestionMustBeBinary = 6013,

        /// Squads proposal must be in Draft status
        InvalidSquadsProposalStatus = 6014,

        /// Casting overflow. If you're seeing this, please report this
        CastingOverflow = 6015,

        /// Insufficient balance
        InsufficientBalance = 6016,

        /// Cannot remove zero liquidity
        ZeroLiquidityRemove = 6017,

        /// Swap slippage exceeded
        SwapSlippageExceeded = 6018,

        /// Assert failed
        AssertFailed = 6019,

        /// Invalid admin
        InvalidAdmin = 6020,

        /// Proposal is not in draft state
        ProposalNotInDraftState = 6021,

        /// Insufficient token balance
        InsufficientTokenBalance = 6022,

        /// Invalid amount
        InvalidAmount = 6023,

        /// Insufficient stake to launch proposal
        InsufficientStakeToLaunch = 6024,

        /// Staker not found in proposal
        StakerNotFound = 6025,

        /// Pool must be in spot state
        PoolNotInSpotState = 6026,

        /// If you're providing liquidity, you must provide both base and quote
        /// token accounts
        InvalidDaoCreateLiquidity = 6027,

        /// Invalid stake account
        InvalidStakeAccount = 6028,

        /// An invariant was violated. You should get in contact with the
        /// MetaDAO team if you see this
        InvariantViolated = 6029,

        /// Proposal needs to be active to perform a conditional swap
        ProposalNotActive = 6030,

        /// This Squads transaction should only contain calls to update spending
        /// limits
        InvalidTransaction = 6031,

        /// Proposal has already been sponsored
        ProposalAlreadySponsored = 6032,

        /// Team sponsored pass threshold must be between -10% and 10%
        InvalidTeamSponsoredPassThreshold = 6033,

        /// Target K must be greater than the current K
        InvalidTargetK = 6034,

        /// Failed to compile transaction message for Squads vault transaction
        InvalidTransactionMessage = 6035,
    }

    impl FutarchyError {
        /// Get the error code
        pub fn code(&self) -> u32 {
            *self as u32
        }

        /// Get the error message
        pub fn msg(&self) -> &'static str {
            match self {

                Self::AmmTooOld => "Amms must have been created within 5 minutes (counted in slots) of proposal initialization",

                Self::InvalidInitialObservation => "An amm has an `initial_observation` that doesn't match the `dao`'s config",

                Self::InvalidMaxObservationChange => "An amm has a `max_observation_change_per_update` that doesn't match the `dao`'s config",

                Self::InvalidStartDelaySlots => "An amm has a `start_delay_slots` that doesn't match the `dao`'s config",

                Self::InvalidSettlementAuthority => "One of the vaults has an invalid `settlement_authority`",

                Self::ProposalTooYoung => "Proposal is too young to be executed or rejected",

                Self::MarketsTooYoung => "Markets too young for proposal to be finalized. TWAP might need to be cranked",

                Self::ProposalAlreadyFinalized => "This proposal has already been finalized",

                Self::InvalidVaultNonce => "A conditional vault has an invalid nonce. A nonce should encode the proposal number",

                Self::ProposalNotPassed => "This proposal can't be executed because it isn't in the passed state",

                Self::InsufficientLiquidity => "More liquidity needs to be in the AMM to launch this proposal",

                Self::ProposalDurationTooShort => "Proposal duration must be longer 1 day and longer than 2 times the TWAP start delay",

                Self::PassThresholdTooHigh => "Pass threshold must be less than 10%",

                Self::QuestionMustBeBinary => "Question must have exactly 2 outcomes for binary futarchy",

                Self::InvalidSquadsProposalStatus => "Squads proposal must be in Draft status",

                Self::CastingOverflow => "Casting overflow. If you're seeing this, please report this",

                Self::InsufficientBalance => "Insufficient balance",

                Self::ZeroLiquidityRemove => "Cannot remove zero liquidity",

                Self::SwapSlippageExceeded => "Swap slippage exceeded",

                Self::AssertFailed => "Assert failed",

                Self::InvalidAdmin => "Invalid admin",

                Self::ProposalNotInDraftState => "Proposal is not in draft state",

                Self::InsufficientTokenBalance => "Insufficient token balance",

                Self::InvalidAmount => "Invalid amount",

                Self::InsufficientStakeToLaunch => "Insufficient stake to launch proposal",

                Self::StakerNotFound => "Staker not found in proposal",

                Self::PoolNotInSpotState => "Pool must be in spot state",

                Self::InvalidDaoCreateLiquidity => "If you're providing liquidity, you must provide both base and quote token accounts",

                Self::InvalidStakeAccount => "Invalid stake account",

                Self::InvariantViolated => "An invariant was violated. You should get in contact with the MetaDAO team if you see this",

                Self::ProposalNotActive => "Proposal needs to be active to perform a conditional swap",

                Self::InvalidTransaction => "This Squads transaction should only contain calls to update spending limits",

                Self::ProposalAlreadySponsored => "Proposal has already been sponsored",

                Self::InvalidTeamSponsoredPassThreshold => "Team sponsored pass threshold must be between -10% and 10%",

                Self::InvalidTargetK => "Target K must be greater than the current K",

                Self::InvalidTransactionMessage => "Failed to compile transaction message for Squads vault transaction",

            }
        }

        /// Try to convert from error code
        pub fn from_code(code: u32) -> Option<Self> {
            match code {
                6000 => Some(Self::AmmTooOld),

                6001 => Some(Self::InvalidInitialObservation),

                6002 => Some(Self::InvalidMaxObservationChange),

                6003 => Some(Self::InvalidStartDelaySlots),

                6004 => Some(Self::InvalidSettlementAuthority),

                6005 => Some(Self::ProposalTooYoung),

                6006 => Some(Self::MarketsTooYoung),

                6007 => Some(Self::ProposalAlreadyFinalized),

                6008 => Some(Self::InvalidVaultNonce),

                6009 => Some(Self::ProposalNotPassed),

                6010 => Some(Self::InsufficientLiquidity),

                6011 => Some(Self::ProposalDurationTooShort),

                6012 => Some(Self::PassThresholdTooHigh),

                6013 => Some(Self::QuestionMustBeBinary),

                6014 => Some(Self::InvalidSquadsProposalStatus),

                6015 => Some(Self::CastingOverflow),

                6016 => Some(Self::InsufficientBalance),

                6017 => Some(Self::ZeroLiquidityRemove),

                6018 => Some(Self::SwapSlippageExceeded),

                6019 => Some(Self::AssertFailed),

                6020 => Some(Self::InvalidAdmin),

                6021 => Some(Self::ProposalNotInDraftState),

                6022 => Some(Self::InsufficientTokenBalance),

                6023 => Some(Self::InvalidAmount),

                6024 => Some(Self::InsufficientStakeToLaunch),

                6025 => Some(Self::StakerNotFound),

                6026 => Some(Self::PoolNotInSpotState),

                6027 => Some(Self::InvalidDaoCreateLiquidity),

                6028 => Some(Self::InvalidStakeAccount),

                6029 => Some(Self::InvariantViolated),

                6030 => Some(Self::ProposalNotActive),

                6031 => Some(Self::InvalidTransaction),

                6032 => Some(Self::ProposalAlreadySponsored),

                6033 => Some(Self::InvalidTeamSponsoredPassThreshold),

                6034 => Some(Self::InvalidTargetK),

                6035 => Some(Self::InvalidTransactionMessage),

                _ => None,
            }
        }
    }

    impl std::fmt::Display for FutarchyError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}: {}", self.code(), self.msg())
        }
    }

    impl std::error::Error for FutarchyError {}

