    /// Program errors for price_based_performance_package
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum PricebasedperformancepackageError {
        /// Unlock timestamp has not been reached yet
        UnlockTimestampNotReached = 6000,

        /// Unlock timestamp must be in the future
        UnlockTimestampInThePast = 6001,

        /// Performance package is not in the expected state
        InvalidPerformancePackageState = 6002,

        /// TWAP calculation failed
        TwapPeriodNotElapsed = 6003,

        /// Price threshold not met
        PriceThresholdNotMet = 6004,

        /// Invalid oracle account data
        InvalidOracleData = 6005,

        /// Unauthorized to create or execute change request
        UnauthorizedChangeRequest = 6006,

        /// Change request does not match locker
        InvalidChangeRequest = 6007,

        /// Unauthorized locker authority
        UnauthorizedLockerAuthority = 6008,

        /// An invariant was violated. You should get in contact with the
        /// MetaDAO team if you see this
        InvariantViolated = 6009,

        /// Tranche price thresholds must be monotonically increasing
        TranchePriceThresholdsNotMonotonic = 6010,

        /// Tranche token amount must be greater than 0
        TrancheTokenAmountZero = 6011,

        /// TWAP length must be greater than or equal to 1 day and less than 1
        /// year
        InvalidTwapLength = 6012,

        /// Invalid admin
        InvalidAdmin = 6013,

        /// Total token amount calculation would overflow
        TotalTokenAmountOverflow = 6014,
    }

    impl PricebasedperformancepackageError {
        /// Get the error code
        pub fn code(&self) -> u32 {
            *self as u32
        }

        /// Get the error message
        pub fn msg(&self) -> &'static str {
            match self {

                Self::UnlockTimestampNotReached => "Unlock timestamp has not been reached yet",

                Self::UnlockTimestampInThePast => "Unlock timestamp must be in the future",

                Self::InvalidPerformancePackageState => "Performance package is not in the expected state",

                Self::TwapPeriodNotElapsed => "TWAP calculation failed",

                Self::PriceThresholdNotMet => "Price threshold not met",

                Self::InvalidOracleData => "Invalid oracle account data",

                Self::UnauthorizedChangeRequest => "Unauthorized to create or execute change request",

                Self::InvalidChangeRequest => "Change request does not match locker",

                Self::UnauthorizedLockerAuthority => "Unauthorized locker authority",

                Self::InvariantViolated => "An invariant was violated. You should get in contact with the MetaDAO team if you see this",

                Self::TranchePriceThresholdsNotMonotonic => "Tranche price thresholds must be monotonically increasing",

                Self::TrancheTokenAmountZero => "Tranche token amount must be greater than 0",

                Self::InvalidTwapLength => "TWAP length must be greater than or equal to 1 day and less than 1 year",

                Self::InvalidAdmin => "Invalid admin",

                Self::TotalTokenAmountOverflow => "Total token amount calculation would overflow",

            }
        }

        /// Try to convert from error code
        pub fn from_code(code: u32) -> Option<Self> {
            match code {
                6000 => Some(Self::UnlockTimestampNotReached),

                6001 => Some(Self::UnlockTimestampInThePast),

                6002 => Some(Self::InvalidPerformancePackageState),

                6003 => Some(Self::TwapPeriodNotElapsed),

                6004 => Some(Self::PriceThresholdNotMet),

                6005 => Some(Self::InvalidOracleData),

                6006 => Some(Self::UnauthorizedChangeRequest),

                6007 => Some(Self::InvalidChangeRequest),

                6008 => Some(Self::UnauthorizedLockerAuthority),

                6009 => Some(Self::InvariantViolated),

                6010 => Some(Self::TranchePriceThresholdsNotMonotonic),

                6011 => Some(Self::TrancheTokenAmountZero),

                6012 => Some(Self::InvalidTwapLength),

                6013 => Some(Self::InvalidAdmin),

                6014 => Some(Self::TotalTokenAmountOverflow),

                _ => None,
            }
        }
    }

    impl std::fmt::Display for PricebasedperformancepackageError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}: {}", self.code(), self.msg())
        }
    }

    impl std::error::Error for PricebasedperformancepackageError {}

