    // ------------------------------------------------------------------------

    /// Program errors for bid_wall
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum BidwallError {
        /// Bid wall expired
        BidWallExpired = 6000,

        /// Bid wall not expired
        BidWallNotExpired = 6001,

        /// Fee recipient mismatch
        FeeRecipientMismatch = 6002,

        /// Insufficient quote reserves
        InsufficientQuoteReserves = 6003,

        /// Bid wall depleted
        BidWallDepleted = 6004,

        /// Invalid input amount
        InvalidInputAmount = 6005,

        /// Invalid crank address
        InvalidCrankAddress = 6006,

        /// Insufficient output amount
        InsufficientOutputAmount = 6007,
    }

    impl BidwallError {
        /// Get the error code
        pub fn code(&self) -> u32 {
            *self as u32
        }

        /// Get the error message
        pub fn msg(&self) -> &'static str {
            match self {
                Self::BidWallExpired => "Bid wall expired",

                Self::BidWallNotExpired => "Bid wall not expired",

                Self::FeeRecipientMismatch => "Fee recipient mismatch",

                Self::InsufficientQuoteReserves => "Insufficient quote reserves",

                Self::BidWallDepleted => "Bid wall depleted",

                Self::InvalidInputAmount => "Invalid input amount",

                Self::InvalidCrankAddress => "Invalid crank address",

                Self::InsufficientOutputAmount => "Insufficient output amount",
            }
        }

        /// Try to convert from error code
        pub fn from_code(code: u32) -> Option<Self> {
            match code {
                6000 => Some(Self::BidWallExpired),

                6001 => Some(Self::BidWallNotExpired),

                6002 => Some(Self::FeeRecipientMismatch),

                6003 => Some(Self::InsufficientQuoteReserves),

                6004 => Some(Self::BidWallDepleted),

                6005 => Some(Self::InvalidInputAmount),

                6006 => Some(Self::InvalidCrankAddress),

                6007 => Some(Self::InsufficientOutputAmount),

                _ => None,
            }
        }
    }

    impl std::fmt::Display for BidwallError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}: {}", self.code(), self.msg())
        }
    }

    impl std::error::Error for BidwallError {}

